"""Real HTTP/IndexedDB/worker regressions; writer fences and full state assertions remain active."""
import argparse,json,unittest
from pathlib import Path
from test_boot_hotfix import BootHotfix
from test_continuity import RecordedResult
class CatchupReliability(BootHotfix):
 def ready(self):
  p=self.raw_page();p.goto(self.url+'/icarus.html?icarus_soak=1');p.wait_for_function('window.__icarusSoak&&ICARUSHost.canWrite()');p.locator('.boot-observe').click();return p
 def test_perf_pending_mirror_restart_uses_verified_database_without_recovery_or_state_loss(self):
  p=self.raw_page();p.context.add_init_script("""window.cacheJobs=[];const OriginalWorker=Worker;window.Worker=class extends OriginalWorker{constructor(url,...args){super(url,...args);if(String(url).includes('save-cache-worker')){const send=this.postMessage.bind(this);this.postMessage=m=>{window.cacheJobs.push(m);window.releaseCache=()=>send(m);};}}};""");p.goto(self.url+'/icarus.html?icarus_soak=1');p.wait_for_function('window.__icarusSoak&&ICARUSHost.canWrite()');p.locator('.boot-observe').click();p.evaluate('__icarusSoak.advance(20)');self.assertTrue(p.evaluate('__icarusSoak.save()'));p.evaluate('ICARUSDurable.flush()');p.wait_for_function('cacheJobs.length>0');before=p.evaluate('__icarusSoak.snapshot()');self.assertGreater(p.evaluate('ICARUSDurable.status.cachePending'),0);p.reload();p.wait_for_function('window.__icarusSoak&&ICARUSHost.canWrite()');self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before);self.assertEqual(p.evaluate('ICARUSDurable.status.recoveries'),0);self.assertEqual(p.evaluate('ICARUSDurable.status.backend'),'indexeddb')
 def test_perf_worker_failure_keeps_canonical_snapshot_and_reports_cache_error(self):
  p=self.raw_page();p.context.add_init_script("const OriginalWorker=Worker;window.Worker=class extends OriginalWorker{constructor(url,...args){if(String(url).includes('save-cache-worker'))throw Error('Controlled worker unavailable');super(url,...args);}};");p.goto(self.url+'/icarus.html?icarus_soak=1');p.wait_for_function('window.__icarusSoak&&ICARUSHost.canWrite()');p.locator('.boot-observe').click();p.evaluate('__icarusSoak.advance(17)');p.evaluate('__icarusSoak.save()');p.evaluate('ICARUSDurable.flush()');p.wait_for_function('ICARUSDurable.status.cacheWarning?.includes("Controlled")');before=p.evaluate('__icarusSoak.snapshot()');p.reload();p.wait_for_function('window.__icarusSoak&&ICARUSHost.canWrite()');self.assertEqual(p.evaluate('__icarusSoak.snapshot()'),before);self.assertTrue(p.evaluate('ICARUSDurable.canWrite()'))
 def test_perf_changed_history_same_id_is_persisted_but_unchanged_history_is_not_rewritten(self):
  p=self.ready();p.evaluate("ICARUSDurable.record({id:'PERF-EVENT',minute:480,episode:1,people:[],kind:'fixture',message:'original'});");p.evaluate('ICARUSDurable.flush()');n=p.evaluate('ICARUSDurable.status.historyRowsWritten');p.evaluate("ICARUSDurable.record({id:'PERF-EVENT',minute:480,episode:1,people:[],kind:'fixture',message:'original'});");p.evaluate('ICARUSDurable.flush()');self.assertEqual(p.evaluate('ICARUSDurable.status.historyRowsWritten'),n);p.evaluate("ICARUSDurable.record({id:'PERF-EVENT',minute:480,episode:1,people:[],kind:'fixture',message:'updated'});");p.evaluate('ICARUSDurable.flush()');self.assertEqual(p.evaluate('(async()=>((await ICARUSDurable.history()).find(r=>r.id==="PERF-EVENT")).message)()'),'updated')
 def test_perf_atomic_import_invalidates_committed_history_dedup_cache(self):
  p=self.ready();p.evaluate('__icarusSoak.save()');p.evaluate("ICARUSDurable.record({id:'PERF-IMPORT',minute:480,people:[],message:'cached'});");p.evaluate('ICARUSDurable.flush()');p.evaluate("""(async()=>{const token=await ICARUSDurable.beginImport();await ICARUSDurable.stageImport(token,[{id:'PERF-IMPORT',minute:480,people:[],message:'imported'}]);await ICARUSDurable.commitImport(token,localStorage.getItem('icarus-v02'));ICARUSDurable.record({id:'PERF-IMPORT',minute:480,people:[],message:'cached'});await ICARUSDurable.flush();})()""");self.assertEqual(p.evaluate('(async()=>((await ICARUSDurable.history()).find(r=>r.id==="PERF-IMPORT")).message)()'),'cached')
 def test_perf_preview_rejection_backoff_does_not_starve_authorized_commands_or_lease(self):
  p=self.ready();p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")');p.evaluate("window.previewCalls=0;window.originalPrepare=ICARUSTelemetryPacket.prepare;ICARUSTelemetryPacket.prepare=()=>{window.previewCalls++;const e=Error('Controlled oversized essential preview');e.name='TelemetryPreviewError';throw e;};__icarusSoak.advance(1);");p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("TELEMETRY PREVIEW ERROR")');code,d=self.req('/api/icarus/dispatch',{'command':'nav:hold','requestId':'perf-command'},{'Authorization':'Bearer test-client'});self.assertEqual(code,200);p.wait_for_function('__icarusSoak.snapshot().navigation.hold');p.wait_for_timeout(3000);self.assertLessEqual(p.evaluate('previewCalls'),3);self.assertTrue(p.evaluate('ICARUSHost.canWrite()&&ICARUSDurable.canWrite()'));p.evaluate('ICARUSTelemetryPacket.prepare=originalPrepare;');p.wait_for_function('document.querySelector("#rd-bridge-status").textContent.includes("LINKED")')
 def test_perf_worker_cache_matches_complete_primary_and_previous_canonical_recovery(self):
  p=self.ready();p.evaluate('__icarusSoak.advance(3)');p.evaluate('__icarusSoak.save()');p.evaluate('ICARUSDurable.flush({cache:true})');previous=p.evaluate('localStorage.getItem("icarus-v02")');p.evaluate('__icarusSoak.advance(3)');p.evaluate('__icarusSoak.save()');p.evaluate('ICARUSDurable.flush({cache:true})');self.assertEqual(p.evaluate('ICARUSSaveStore.decode(ICARUSSaveStore.encodedGet("icarus-core-recovery-v0941"))'),previous);self.assertEqual(p.evaluate('ICARUSSaveStore.decode(ICARUSSaveStore.encodedGet("icarus-v02"))'),p.evaluate('localStorage.getItem("icarus-v02")'))
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--report',type=Path,required=True);ap.add_argument('--runtime',type=Path);a=ap.parse_args()
 if a.runtime:
  import test_umbra_browser
  test_umbra_browser.ROOT=a.runtime.resolve()
 names=[n for n in unittest.defaultTestLoader.getTestCaseNames(CatchupReliability) if n.startswith('test_perf_')];r=unittest.TextTestRunner(verbosity=2,resultclass=RecordedResult).run(unittest.TestSuite(CatchupReliability(n) for n in names));a.report.write_text(json.dumps({'passed':r.wasSuccessful(),'tests_run':r.testsRun,'passed_cases':r.successes,'failures':[{'test':str(t),'detail':d[:6000]} for t,d in r.failures],'errors':[{'test':str(t),'detail':d[:6000]} for t,d in r.errors]},indent=2));raise SystemExit(not r.wasSuccessful())
